static int repetitions = 1;
module_param(repetitions, int, 0444);   /* lisible dans /sys/module/.../parameters */
MODULE_PARM_DESC(repetitions, "Nombre de messages au chargement (1 à 10)");

static int __init bonjour_init(void)
{
    int i;

    if (repetitions < 1 || repetitions > 10)
        return -EINVAL;                  /* insmod : Invalid argument */
    for (i = 0; i < repetitions; i++)
        pr_info("bonjour %d/%d\n", i + 1, repetitions);
    return 0;
}

static void __exit bonjour_exit(void)
{
    pr_info("au revoir\n");
}

module_init(bonjour_init);
module_exit(bonjour_exit);
