#include <linux/module.h>
#include <linux/fs.h>
#include <linux/cdev.h>
#include <linux/device.h>
#include <linux/uaccess.h>

#define TAILLE 256
static char tampon[TAILLE] = "Bonjour depuis le noyau\n";
static size_t longueur = 24;
static dev_t num;
static struct cdev mon_cdev;
static struct class *classe;

static ssize_t mon_read(struct file *f, char __user *buf, size_t n, loff_t *pos)
{
    if (*pos >= longueur)
        return 0;                              /* fin de fichier */
    n = min(n, longueur - (size_t)*pos);
    if (copy_to_user(buf, tampon + *pos, n))
        return -EFAULT;
    *pos += n;
    return n;
}

static ssize_t mon_write(struct file *f, const char __user *buf, size_t n, loff_t *pos)
{
    n = min(n, (size_t)TAILLE);
    if (copy_from_user(tampon, buf, n))
        return -EFAULT;
    longueur = n;
    return n;
}

static const struct file_operations mon_fops = {
    .owner = THIS_MODULE,
    .read  = mon_read,
    .write = mon_write,
};

static int __init mon_init(void)
{
    int ret = alloc_chrdev_region(&num, 0, 1, "memo");
    if (ret)
        return ret;
    cdev_init(&mon_cdev, &mon_fops);
    ret = cdev_add(&mon_cdev, num, 1);
    if (ret)
        goto err_region;
    classe = class_create("memo");         /* avant 6.4 : class_create(THIS_MODULE, "memo") */
    if (IS_ERR(classe)) {
        ret = PTR_ERR(classe);
        goto err_cdev;
    }
    device_create(classe, NULL, num, NULL, "memo");   /* -> /dev/memo */
    return 0;
err_cdev:
    cdev_del(&mon_cdev);
err_region:
    unregister_chrdev_region(num, 1);
    return ret;
}

static void __exit mon_exit(void)
{
    device_destroy(classe, num);
    class_destroy(classe);
    cdev_del(&mon_cdev);
    unregister_chrdev_region(num, 1);
}

module_init(mon_init);
module_exit(mon_exit);
MODULE_LICENSE("GPL");

