static int mon_probe(struct platform_device *pdev)
{
    u32 periode = 500;    /* valeur par défaut */

    of_property_read_u32(pdev->dev.of_node, "embedforge,periode-ms", &periode);
    dev_info(&pdev->dev, "période : %u ms\n", periode);
    return 0;
}

static const struct of_device_id mon_of_match[] = {
    { .compatible = "embedforge,clignotant" },
    { }                   /* sentinelle obligatoire */
};
MODULE_DEVICE_TABLE(of, mon_of_match);

static struct platform_driver mon_driver = {
    .probe = mon_probe,
    .driver = {
        .name = "clignotant",
        .of_match_table = mon_of_match,
    },
};
module_platform_driver(mon_driver);

